import csv, re
from collections import Counter, defaultdict
from pathlib import Path
accs={'2025-q2':'0000950123-25-008343','2025-q3':'0001193125-25-282901'}
def num(value):
    text=(value or '').strip().replace(',','').replace('$','')
    return float(text) if text else 0.0
snapshots={}
for quarter,acc in accs.items():
    rows=[]
    with (Path('/root')/quarter/'INFOTABLE.tsv').open(newline='', encoding='utf-8-sig') as f:
        for r in csv.DictReader(f, delimiter='\t'):
            if r['ACCESSION_NUMBER']==acc:
                rows.append(r)
    by=defaultdict(float)
    for r in rows: by[str(r['CUSIP']).strip()]+=num(r['VALUE'])
    snapshots[quarter]=by
    counts=Counter(r['CUSIP'] for r in rows)
    print(quarter,'rows',len(rows),'unique cusips',len(by),'duplicates',[x for x,n in counts.items() if n>1][:10])
changes=[]
