    rows=[]
    with (Path('/root')/quarter/'INFOTABLE.tsv').open(newline='', encoding='utf-8-sig') as f:
        for r in csv.DictReader(f, delimiter='\t'):
            if r['ACCESSION_NUMBER']==acc:
                rows.append(r)
    by=defaultdict(float)
